def min_draws_to_win(tiles):
    def is_koutsu(tiles):
        return len(set(tiles)) == 1

    def is_shuntsu(tiles):
        suit = [tile[1] for tile in tiles]
        numbers = sorted([int(tile[0]) for tile in tiles])
        return suit[0] == suit[1] == suit[2] and numbers[1] == numbers[0] + 1 and numbers[2] == numbers[1] + 1

    tiles.sort()
    if is_koutsu(tiles) or is_shuntsu(tiles):
        return 0

    same_suit_groups = {}
    for tile in tiles:
        suit = tile[1]
        number = int(tile[0])
        if suit not in same_suit_groups:
            same_suit_groups[suit] = []
        same_suit_groups[suit].append(number)

    for suit, numbers in same_suit_groups.items():
        if len(numbers) == 2:
            n1, n2 = numbers
            if n1 == n2 or abs(n1 - n2) <= 2:
                return 1

    # If none of the above cases hold, she needs to draw 2 tiles to ensure a mentsu
    return 2

# Read input
tiles = input().strip().split()
# Output the result
print(min_draws_to_win(tiles))

