def max_beauty_after_swap(n, trophies):
    golden_segments = []
    current_g_count = 0
    total_golden = 0

    for trophy in trophies:
        if trophy == 'G':
            current_g_count += 1
            total_golden += 1
        else:
            if current_g_count > 0:
                golden_segments.append(current_g_count)
                current_g_count = 0

    if current_g_count > 0:
        golden_segments.append(current_g_count)

    # If no golden trophies exist
    if total_golden == 0:
        return 0

    # If all are golden trophies
    if len(golden_segments) == 1:
        return golden_segments[0]

    # Compute max achievable beauty
    max_beauty = 0

    for i in range(len(golden_segments) - 1):
        current_beauty = golden_segments[i] + golden_segments[i + 1]
        if golden_segments[i] + golden_segments[i + 1] < total_golden:
            current_beauty += 1
        max_beauty = max(max_beauty, current_beauty)

    # Compare with each segment length alone, but increased by one if possible
    for g in golden_segments:
        if g < total_golden:
            max_beauty = max(max_beauty, g + 1)

    return max_beauty

