main_courses = [5, 3]
dependencies = {
    1: [],
    2: [],
    3: [],
    4: [2, 1],
    5: [4],
    6: [5]
}
m, course_order = find_min_courses_to_pass(n, k, main_courses, dependencies)
if m == -1:
    print(m)
else:
    print(m)
    print(' '.join(map(str, course_order)))

