from collections import defaultdict, deque

def find_min_courses_to_pass(n, k, main_courses, dependencies):
    # Create graph and in-degree array
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    # Build the graph and compute in-degrees
    for course, reqs in dependencies.items():
        for req in reqs:
            graph[req].append(course)
            in_degree[course] += 1

    # Start with courses that have in-degree 0
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    # Topologically sort and collect required courses
    topological_order = []
    visited_courses = set()
    while queue:
        course = queue.popleft()
        topological_order.append(course)

        for next_course in graph[course]:
            in_degree[next_course] -= 1
            if in_degree[next_course] == 0:
                queue.append(next_course)

    # Check if all main courses are in the topological order
    needed_courses = set(main_courses)
    completed_courses = []
    for course in topological_order:
        if course in needed_courses or course in visited_courses:
            completed_courses.append(course)
            visited_courses.add(course)
            needed_courses.discard(course)
        if not needed_courses:
            break

    if needed_courses:
        return -1, []
    else:
        return len(completed_courses), completed_courses

